async function buscarClima(cidade) {
  const resposta = await fetch(`https://api.exemplo.com/clima?cidade=${cidade}`);
  const dados = await resposta.json();   // dois await: resposta e corpo
  return dados;
}

async function buscarClima(cidade) {
  try {
    const r = await fetch(url(cidade));
    if (!r.ok) {                       // 404, 429... não rejeitam o fetch
      return { erro: r.status === 404 ? 'cidade não encontrada' : 'tente mais tarde' };
    }
    return await r.json();
  } catch {
    return { erro: 'sem conexão' };    // falha de rede cai aqui
  }
}

